fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries
        .into_iter()
        .map(|n| {
            if n >= 4 {
                // If already at least 4, we only need to add 0 or 1
                // to make it even (n % 2 is 0 for even, 1 for odd)
                n % 2
            } else {
                // If it's less than 4, we must bump it up to 4
                4 - n
            }
        })
        .collect()
}

