        // For 3 -> 4-3 = 1
        // For 4 -> 4>=4, 4%2 = 0
        // For 5 -> 5>=4, 5%2 = 1
        // For 6 -> 6>=4, 6%2 = 0
        // For 7 -> 7>=4, 7%2 = 1
        // For 8 -> 8>=4, 8%2 = 0
        assert_eq!(result, vec![2, 1, 0, 1, 0, 1, 0]);
